import{_ as s,a0 as p,w as o,s as d,I as t,x as n,a1 as l,A as a,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"Linux Defenders怎樣先發制人阻止惡意軟件專利被批准 | LCTT x X-CMD","titleTemplate":false,"description":"Linux Defenders怎樣先發制人阻止惡意軟件專利被批准 | LCTT (201309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux Defenders怎樣先發制人阻止惡意軟件專利被批准 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux Defenders怎樣先發制人阻止惡意軟件專利被批准 | LCTT (201309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201309/How Linux defenders attack bad software patents before they’re approved","title":"Linux Defenders怎樣先發制人阻止惡意軟件專利被批准","tag":"201309","desc":""},"relativePath":"201309/How Linux defenders attack bad software patents before they’re approved.md","filePath":"[post].md"}'),u={name:"201309/How Linux defenders attack bad software patents before they’re approved.md"};function f(x,e,L,C,m,w){const r=p("Link");return o(),d("div",null,[e[17]||(e[17]=t("h1",{id:"linux-defenders怎樣先發制人阻止惡意軟件專利被批准",tabindex:"-1"},[n("Linux Defenders怎樣先發制人阻止惡意軟件專利被批准 "),t("a",{class:"header-anchor",href:"#linux-defenders怎樣先發制人阻止惡意軟件專利被批准","aria-label":"Permalink to “Linux Defenders怎樣先發制人阻止惡意軟件專利被批准”"},"​")],-1)),e[18]||(e[18]=t("p",null,[t("strong",null,[t("em",null,"這個小組識別危險的專利並且試着還原它們的本來面目。")])],-1)),e[19]||(e[19]=t("p",null,[t("img",{src:"http://cdn.arstechnica.net/wp-content/uploads/2013/09/linux-penguin.jpg",alt:""})],-1)),e[20]||(e[20]=t("p",null,"儘管那些“專利蟑螂”發起影響開源軟件的訴訟數目與日俱增，但還有一線希望。2011年9月簽署了一部法律-《美國發明法案》，它提供了新的途徑來阻止未來可能引起訴訟的過於寬泛的軟件專利。",-1)),t("p",null,[e[1]||(e[1]=n("今天的 LinuxCon的一個會議中，",-1)),l(r,{href:"http://linuxdefenders.org/"},{default:a(()=>[...e[0]||(e[0]=[n("Linux Defenders",-1)])]),_:1}),e[2]||(e[2]=n(" 的負責人Andrea Casillas解釋了這個組織是如何利用新法律賦予的權利來對抗專利申請。Open Invention Network 的一個項目 Software Freedom Law Center，Linux 基金會以及 Linux Defenders 對每週公佈的6000項專利做檢查，試圖識別出那些對Linux和開源的潛在威脅。然後，這個組織查找一些至少能夠廢止其中一部分專利申請的先例。",-1))]),e[21]||(e[21]=t("p",null,"下一步就是協同Linux技術專家編纂防禦性公共出版物，雖然它們本身不是專利，但它們描述了一項發明，並放入公開檔案以阻止覆含該技術的新專利的批准。這些出版物通常有2-3頁的技術描述，美國專利商標局的審查員可以在管理可能會失效的先例或者限制新專利申請的範圍時閲讀參考。",-1)),e[22]||(e[22]=t("p",null,"“我們將與作者、發明者或者開發者攜手合作編寫這些出版物，使它們更加有效。” Casillas 説。他一直主張 Linux 社區幫助這個小組發現危險專利並尋找先例。",-1)),e[23]||(e[23]=t("p",null,"防禦性公共出版物是舊的策略，但它將會因為 America Ivents Act 而越來越接近公眾的生活。Casillas 解釋説：“這是審查人員第一次歡迎公眾的互動。任何個人都可以免費遞交電子版的關於先例的申請。”",-1)),e[24]||(e[24]=t("p",null,"Linux Defenders 已經編纂好了與來自 Microsoft，Apple和其它公司的專利申請有關的防禦性公共出版物。概括來説，Casillas 説防禦性公共出版物不是要去迫使某家公司放棄某一專利，而是要迫使某家公司縮小它們申請的專利包括的範圍。",-1)),e[25]||(e[25]=t("p",null,"當被問起 Linux Defenders 能否説出因為這個過程而受限的專利申請的案例時，Casillas 和她的同事們説他們仍然在尋找評估它的有效性的方法。在6到9個月裏，他們希望能找到一個工具來跟蹤記錄專利研究者們在複審中使用防禦性公共出版物的情況。",-1)),e[26]||(e[26]=t("p",null,"Linux Denfenders 同時也把矛頭指向已經通過的專利。但 Casillas 提醒説要推倒已經批准的專利的法律標準非常高。",-1)),e[27]||(e[27]=t("p",null,"###專利訴訟“能讓 Red Hat掃地出門”",-1)),e[28]||(e[28]=t("p",null,"昨天 LinuxCon 的一個單獨的會議上，Red Hat 的 Fedora 項目經理 Tom Callaway 討論了開源的法律威脅。",-1)),t("p",null,[e[4]||(e[4]=n("Red Hat 批評了“專利蟑螂”並且採取多種措施",-1)),l(r,{href:"http://www.networkworld.com/news/2011/050511-red-hat-ceo-patents.html"},{default:a(()=>[...e[3]||(e[3]=[n("保護自己和用户",-1)])]),_:1}),e[5]||(e[5]=n("。Callaway 説不能小看這些威脅。“我不是説大話，Red Hat在我們開源產業裏不是一個小公司，我們可能是最大的。一個關鍵專利訴訟的失利可以讓 Red Hat在這行幹不下去。這就是專利的重要性，也足見在業界它是多麼讓人聞風喪膽。”",-1))]),e[29]||(e[29]=i("<p>各種可能性中，Red Hat不會被掃地出門的。它有一個保護自己及用户的在法庭上對抗專利“專利蟑螂”的良好跟蹤記錄。它把保障用户權益、對抗訴訟當做它的軟件程序，而且已經建立起了一系列防禦專利。</p><p>儘管付費的 RHEL 會員資格給了用户額外的保護，Red Hat也正在保證Fedora這個免費的系統遠離法律糾紛。它是這麼做的：分析所有代碼，確保每段代碼都使用合適的許可，有時移除或重寫有嫌疑的代碼。這會導致軟件產生負面的結果。“我們在 Fedora 中遇到了很多問題。專利使我們不能按照我們所想要的方式去做事。”Callaway 這麼説。</p><p>在最近的與 Rackspace 和 Red Hat 有關的案子裏，一個叫做 Uniloc 公司想要從 Rackspace 處獲得費用，因為後者使用了Red Hat的基於 Linux 的服務器。Uniloc的案子以其敗訴告終。法官宣判它的專利聲明無效，因為它僅描述了一個相對簡單的數學操作。</p><p>但是應對這些訴訟很費錢。甚至 Red Hat 有時付專利費避免打官司。</p><p>Callaway在過分寬泛的專利面前流露出了挫敗感。某些專利是“如此的模糊以至於它們可以指任何東西，”他説，“它們可以被應用到幾乎任何地方，並且專利持有者打賭認定你不會去計較。”</p><p>###幫助專利審查人員識別惡意專利</p><p>Casillas告訴我們，那些過分寬泛的專利，正是 Linux Defenders 想要去阻止的。模糊的專利經常能夠通過專利申請，部分原因是因為專利審查人員用在每個申請上的時間不會超過20小時。</p><p>總的時間是“相當難以置信，它考慮到這個過程所需時間長短以及這個專利發佈的重要性。”他説。那20小時“包括了瀏覽申請，確定它按格式編輯，你的基本合法需求，而且這段時間決定着這個發明的前景。”</p><p>專利審查人員用7到8個小時搜索先例，不論是專利形式的還是其它公共可及的技術描述，她説。</p><p>通過提交防禦性公共出版物，提取標籤以使專利審查人員更容易找到，Linux Defenders 希望使美國專利商標局更加起到實際作用。</p><p>Casillas 説：“我們不是在增加他們的工作量，而是幫助他們一起完成這些相關出版物”</p>",11)),t("p",null,[e[7]||(e[7]=n("via: ",-1)),l(r,{href:"http://arstechnica.com/tech-policy/2013/09/how-linux-defenders-attack-software-patents-before-theyre-approved/"},{default:a(()=>[...e[6]||(e[6]=[n("http://arstechnica.com/tech-policy/2013/09/how-linux-defenders-attack-software-patents-before-theyre-approved/",-1)])]),_:1})]),t("p",null,[e[10]||(e[10]=n("本文由 ",-1)),l(r,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[8]||(e[8]=[n("LCTT",-1)])]),_:1}),e[11]||(e[11]=n(" 原創翻譯，",-1)),l(r,{href:"http://linux.cn/portal.php"},{default:a(()=>[...e[9]||(e[9]=[n("Linux中國",-1)])]),_:1}),e[12]||(e[12]=n(" 榮譽推出",-1))]),t("p",null,[e[15]||(e[15]=n("譯者：",-1)),l(r,{href:"http://linux.cn/space/boredivan"},{default:a(()=>[...e[13]||(e[13]=[n("boredivan",-1)])]),_:1}),e[16]||(e[16]=n(" 校對：",-1)),l(r,{href:"http://linux.cn/space/14763"},{default:a(()=>[...e[14]||(e[14]=[n("Caroline",-1)])]),_:1})])])}const k=s(u,[["render",f]]);export{b as __pageData,k as default};
